function validate([quality, wage, k]) {
  const n = quality.length;
  if (n < 1 || n > 10000) return 'quality needs 1 to 10^4 values.';
  if (wage.length !== n) return 'quality and wage must have the same length.';
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is between 1 and the number of workers.';
  if (quality.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each quality is a whole number from 1 to 10^4.';
  if (wage.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each wage is a whole number from 1 to 10^4.';
  return null;
}

