function mincostToHireWorkers(quality, wage, k) {
  const workers = quality.map((q, i) => [wage[i] / q, q]);
  workers.sort((a, b) => a[0] - b[0]);

  const heap = [];
  const push = (value) => {
    heap.push(value);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent] >= heap[i]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let i = 0;
    while (true) {
      const left = 2 * i + 1;
      const right = left + 1;
      let largest = i;
      if (left < heap.length && heap[left] > heap[largest]) largest = left;
      if (right < heap.length && heap[right] > heap[largest]) largest = right;
      if (largest === i) break;
      [heap[largest], heap[i]] = [heap[i], heap[largest]];
      i = largest;
    }
    return top;
  };

  let qualitySum = 0;
  let best = Infinity;
  for (const [ratio, q] of workers) {
    push(q);
    qualitySum += q;
    if (heap.length > k) {
      qualitySum -= pop();
    }
    if (heap.length === k) {
      best = Math.min(best, qualitySum * ratio);
    }
  }
  return best;
}

