function mincostToHireWorkers(quality, wage, k) {
  // Try every group of k workers. The cheapest legal pay rate for a group is the largest wage / quality among its members.
  const n = quality.length;
  const chosen = [];
  let best = Infinity;
  const choose = start => {
    if (chosen.length === k) {
      let rate = 0, total = 0;
      for (const i of chosen) { rate = Math.max(rate, wage[i] / quality[i]); total += quality[i]; }
      best = Math.min(best, rate * total);
      return;
    }
    for (let i = start; i <= n - (k - chosen.length); i++) { chosen.push(i); choose(i + 1); chosen.pop(); }
  };
  choose(0);
  return best;
}

