function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(10);
  const k = rand() < 0.2 ? (rand() < 0.5 ? 1 : n) : 1 + pick(n);
  const top = size === 'large' || rand() < 0.4 ? 10000 : 1 + pick(12);
  const quality = Array.from({ length: n }, () => 1 + pick(top));
  // Sometimes give everyone the same pay rate, so ties between ratios show up.
  const rate = 1 + pick(5);
  const same = size === 'small' && rand() < 0.15 && top * rate <= 10000;
  const wage = quality.map(q => (same ? q * rate : 1 + pick(top)));
  return [quality, wage, k];
}
